/* reader.h - the public, non-virtual interface */
typedef struct reader reader;
ssize_t reader_read(reader *r, void *buf, size_t n);

/* reader.c - the subclass interface */
typedef struct { ssize_t (*read)(reader *, void *, size_t); } reader_ops;
struct reader { const reader_ops *ops; };

ssize_t reader_read(reader *r, void *buf, size_t n) {
    if (!r || !r->ops || n > MAX_READ) return -EINVAL;  /* invariant */
    return r->ops->read(r, buf, n);                     /* extension point */
}
